class Solution { public List<Integer> findMinHeightTrees(int n,int[][] e) { if(n<=2){List<Integer>a=new ArrayList<>();for(int i=0;i<n;i++)a.add(i);return a;}List<Set<Integer>>g=new ArrayList<>();for(int i=0;i<n;i++)g.add(new HashSet<>());for(int[] x:e){g.get(x[0]).add(x[1]);g.get(x[1]).add(x[0]);}List<Integer> q=new ArrayList<>();for(int i=0;i<n;i++)if(g.get(i).size()==1)q.add(i);int left=n;while(left>2){left-=q.size();List<Integer> z=new ArrayList<>();for(int u:q){int v=g.get(u).iterator().next();g.get(v).remove(u);g.get(u).clear();if(g.get(v).size()==1)z.add(v);}q=z;}Collections.sort(q);return q;} }
